import math
GOLD=0.6180339887498949
GA=math.pi*(3-math.sqrt(5))
def kernel(count,radius,seed):
    rot=((seed*2654435761)%1000003)/1000003.0*2*math.pi
    return [(radius*math.sqrt(((i+1)*GOLD)%1.0)*math.cos(i*GA+rot),
             radius*math.sqrt(((i+1)*GOLD)%1.0)*math.sin(i*GA+rot)) for i in range(count)]
w=h=16
data=[[x*0.01+y*0.01 for x in range(w)] for y in range(h)]
rng=max(v for r in data for v in r)-min(v for r in data for v in r)
th=0.1*rng
def ao(count,mode):
    k=kernel(count,4,7); tot=0
    for y in range(h):
        for x in range(w):
            c=data[y][x]; occ=0.0
            for dx,dy in k:
                sx=min(max(int(round(x+dx)),0),w-1); sy=min(max(int(round(y+dy)),0),h-1)
                d=c-data[sy][sx]
                if mode=='bin':
                    if d>1e-12 and d<=th: occ+=1
                else:
                    if d>1e-12: occ+=min(1.0,d/th)
            tot+=1-occ/len(k)
    return tot/(w*h)
for mode in ('bin','soft'):
    print(mode,[round(ao(n,mode),4) for n in (8,16,32,64)])
